        [TestMethod]
        public void TestSortResponseMessages_SGCustomsTest()
        {
            var responseXml = new XmlDocument();
            responseXml.Load(GetEmbeddedResource(filePath + "UnsortedResponseMsg.xml"));

            var sortedMsgExpectedXml = new XmlDocument();
            sortedMsgExpectedXml.Load(GetEmbeddedResource(filePath + "SortedResponseMsg.xml"));

			var sortedMsgXml = MHAccessMessageHelper.SortAIRAEPMessages(responseXml);

			Assert.AreEqual(sortedMsgExpectedXml.InnerXml, sortedMsgXml.InnerXml);
        }

		[TestMethod]
		public void TestSortLargeResponseMessages_SGCustomsTest()
		{
			var responseXml = new XmlDocument();
			responseXml.Load(GetEmbeddedResource(filePath + "UnsortedLargeResponseMsg.xml"));

			var sortedMsgExpectedXml = new XmlDocument();
			sortedMsgExpectedXml.Load(GetEmbeddedResource(filePath + "SortedLargeResponseMsg.xml"));

			var sortedMsgXml = MHAccessMessageHelper.SortAIRAEPMessages(responseXml);

			Assert.AreEqual(sortedMsgExpectedXml.InnerXml, sortedMsgXml.InnerXml);
		}

		Stream GetEmbeddedResource(string resourceName)
        {
            string fullResourceName = Assembly.GetExecutingAssembly().GetName().Name + '.' + resourceName;
            var resource = Assembly.GetExecutingAssembly().GetManifestResourceStream(fullResourceName);
            if (resource == null)
            {
                throw new Exception(String.Format("Could not locate embedded resource '{0}'", fullResourceName));
            }
            return resource;
        }
